('Streak Freeze','Protect one missed day without earning streak XP.','❄',500,'streak_freeze','{}'),('New Theme','Unlock an alternate study room palette.','◐',1000,'theme','{}'),('Special Postcard','Add a rare collection card.','✦',1500,'postcard','{}'),('2× XP Booster','Double the next five eligible task or focus rewards.','×2',750,'xp_booster','{"eligible_actions":5}'::jsonb),('Custom Profile Badge','A permanent profile flourish.','◆',1000,'badge','{}') on conflict(name) do nothing;
insert into public.themes(name,description,preview,price,theme_config) values
('Default','Warm archive paper and ink.','#25372e',0,'{"accent":"#d05b38"}'),('Midnight','A focused dark reading room.','#17232d',1000,'{"accent":"#f0a166"}'),('Forest','Moss, paper, and patient growth.','#36523b',1000,'{"accent":"#b9cc8d"}'),('Cyber','Electric night-study contrast.','#17152c',1000,'{"accent":"#e87dcb"}'),('Study Café','Terracotta and toasted cream.','#6b3b2d',1000,'{"accent":"#f1b66a"}') on conflict(name) do nothing;
