create or replace function public.complete_pomodoro(p_task_id uuid,p_started_at timestamptz,p_duration_minutes integer) returns jsonb language plpgsql security definer set search_path=public as $$ declare sid uuid:=gen_random_uuid(); begin if p_duration_minutes < 1 or p_duration_minutes > 180 then raise exception 'Invalid focus duration'; end if; if p_task_id is not null and not exists(select 1 from tasks where id=p_task_id and user_id=auth.uid()) then raise exception 'Task not found'; end if; insert into pomodoro_sessions(id,user_id,task_id,started_at,ended_at,duration_minutes,completed) values(sid,auth.uid(),p_task_id,p_started_at,now(),p_duration_minutes,true); perform award_xp(auth.uid(),15,'pomodoro','pomodoro',sid); insert into activity_days(user_id,activity_date,pomodoros_completed,focus_minutes,xp_earned,active) values(auth.uid(),current_date,1,p_duration_minutes,15,true) on conflict(user_id,activity_date) do update set pomodoros_completed=activity_days.pomodoros_completed+1,focus_minutes=activity_days.focus_minutes+p_duration_minutes,xp_earned=activity_days.xp_earned+15,active=true,updated_at=now(); return jsonb_build_object('xp',15,'session_id',sid); end $$;
create or replace function public.purchase_shop_item(p_item_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare item shop_items%rowtype; begin select * into item from shop_items where id=p_item_id and active for update; if not found then raise exception 'Item unavailable'; end if; update profiles set total_xp=total_xp-item.price,level=level_for_xp(total_xp-item.price),updated_at=now() where id=auth.uid() and total_xp>=item.price; if not found then raise exception 'Insufficient XP'; end if; insert into xp_transactions(user_id,amount,reason,reference_type,reference_id) values(auth.uid(),-item.price,'shop_purchase','shop',gen_random_uuid()); insert into user_inventory(user_id,item_id,quantity) values(auth.uid(),item.id,1) on conflict(user_id,item_id) do update set quantity=user_inventory.quantity+1,purchased_at=now(); return jsonb_build_object('purchased',item.name,'price',item.price); end $$;
create or replace function public.claim_daily_reward() returns jsonb language plpgsql security definer set search_path=public as $$ declare rid uuid:=gen_random_uuid(); begin insert into daily_rewards(id,user_id,reward_date,reward_type,reward_value,claimed,claimed_at) values(rid,auth.uid(),current_date,'daily_xp',25,true,now()) on conflict(user_id,reward_date) do nothing; if not found then raise exception 'Today''s reward is already claimed'; end if; perform award_xp(auth.uid(),25,'daily_reward','daily_reward',rid); return jsonb_build_object('xp',25); end $$;
grant execute on function public.complete_pomodoro(uuid,timestamptz,integer),public.purchase_shop_item(uuid),public.claim_daily_reward() to authenticated;
